import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { readFile } from "node:fs/promises";

const normalizeBucketName = (name: string): string =>
  name
    .toLowerCase()
    .replace(/[^a-z0-9.-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "");

const main = async (): Promise<void> => {
  const trialId = (await readFile("/logs/artifacts/trial_id", "utf8")).trim();
  if (!trialId) {
    throw new Error("trial id file is empty");
  }

  const workspaceName = normalizeBucketName(`harbor-scoped-${trialId}`);
  const workspace = await createWorkspace(workspaceName, {
    credentials: { role: "Editor" },
  });

  if (!workspace?.bucket) {
    throw new Error("Workspace creation did not return a bucket name.");
  }

  if (!workspace.credentials?.accessKeyId || !workspace.credentials?.secretAccessKey) {
    throw new Error("Workspace creation did not return scoped credentials.");
  }

  try {
    const s3 = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: workspace.credentials.accessKeyId,
        secretAccessKey: workspace.credentials.secretAccessKey,
      },
    });

    await s3.send(
      new PutObjectCommand({
        Bucket: workspace.bucket,
        Key: "greeting.txt",
        Body: "hello scoped",
      })
    );

    console.log(`SCOPED_UPLOAD_OK ${workspace.bucket}`);
  } finally {
    await teardownWorkspace(workspace);
  }
};

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

