const createWorkspaceWithRetry = async (): Promise<Workspace> => {
  let lastError: Error | undefined;

  for (let attempt = 1; attempt <= 5; attempt += 1) {
    const workspaceResponse = await createWorkspace(workspaceName, {
      credentials: { role: "Editor" },
    });

    if (!workspaceResponse.error) {
      return workspaceResponse.data;
    }

    const message = workspaceResponse.error.message ?? "";
    lastError = workspaceResponse.error;

    if (message.includes("bucket name is not available")) {
      await teardownWorkspace({ bucket: workspaceName });
    } else if (!message.includes("recently deleted")) {
      throw workspaceResponse.error;
    }

    if (attempt < 5) {
      await new Promise((resolve) => setTimeout(resolve, 2000 * attempt));
    }
  }

  throw lastError ?? new Error("Workspace creation failed after retries.");
};

const workspace = await createWorkspaceWithRetry();

